    money = { 101 => { company_id: 101, values: {} }, 202 => { company_id: 202, values: {} } }
    projection_before = Marshal.load(Marshal.dump(projection))
    source_rows_before = Marshal.load(Marshal.dump(source.rows))
    checkpoint_rows_before = Marshal.load(Marshal.dump(checkpoint.rows))

    write_statements = []
    watcher = lambda do |*, payload|
      sql = payload[:sql].to_s
      write_statements << sql if sql.match?(/\A\s*(INSERT|UPDATE|DELETE)\b/i)
    end

    result = nil
    ActiveSupport::Notifications.subscribed(watcher, "sql.active_record") do
      result = described_class.run(
        source: source, checkpoint: checkpoint, projection: projection,
        source_intents: [], intents: [], next_entry_id: 100,
        money_before: money, money_after: money
      )
    end

    expect(result.abort?).to be(true)
    expect(write_statements).to eq([])
    expect(projection).to eq(projection_before)
    expect(source.rows).to eq(source_rows_before)
    expect(checkpoint.rows).to eq(checkpoint_rows_before)
    expect(checkpoint.rows["entries"].find { |row| row["company_id"] == 101 }["note"]).to eq("changed")
  end
