RSpec.describe Timekeeping::Handoff::Reconciliation, "repeated run" do
  def repeat_run_entry(id, company_id, duration)
    {
      "id" => id, "company_id" => company_id, "version" => 1, "project_id" => 1, "user_id" => 1, "agent_id" => nil,
