      "review_status" => "not_required", "locked" => false, "source" => "manual", "source_metadata" => {},
      "external_run_id" => nil, "external_session_id" => nil, "proof_url" => nil, "proof_metadata" => {},
      "discarded_at" => nil, "created_at" => Time.utc(2026, 1, 5, 9), "updated_at" => Time.utc(2026, 1, 5, 9)
    }
  end

  def repeat_run_checkpoint(entries)
    tables = Timekeeping::Handoff::Checkpoint::TABLES.keys.index_with { [] }
    tables["entries"] = entries
    Timekeeping::Handoff::Checkpoint.build(tables: tables)
  end

  def repeat_run_projection_row(entry)
    entry.merge(
      "bill_status" => TimesheetEntry.bill_statuses.fetch(entry["bill_status"]),
      "review_status" => TimesheetEntry.review_statuses.fetch(entry["review_status"])
    )
  end

  # "Reconciliation writes nothing and never repairs a difference": a second run reads the same
  # stored values, so it must report exactly what the first run reported.
  it "gives the same per-company report when a resumed handoff runs it again on the same inputs" do
    source_entries = [repeat_run_entry(7, 101, 60.0), repeat_run_entry(7, 202, 60.0)]
    loaded_entries = [repeat_run_entry(7, 101, 60.0.next_float), repeat_run_entry(7, 202, 60.0)]
    inputs = {
      source: repeat_run_checkpoint(source_entries),
      checkpoint: repeat_run_checkpoint(loaded_entries),
      projection: source_entries.map { |entry| repeat_run_projection_row(entry) },
      source_intents: [], intents: [], next_entry_id: 100,
      money_before: { 101 => { company_id: 101, values: {} }, 202 => { company_id: 202, values: {} } },
      money_after: { 101 => { company_id: 101, values: {} }, 202 => { company_id: 202, values: {} } }
    }

    first = described_class.run(**inputs)
    second = described_class.run(**inputs)

    expect(first.to_h).to eq(second.to_h)
    expect(first.abort?).to be(true)
    expect(second.abort?).to be(true)
    expect(second.companies.fetch(101).abort?).to be(true)
    expect(second.companies.fetch(202).abort?).to be(false)
  end
end

RSpec.describe Timekeeping::Handoff::Reconciliation, "listed differences are reported, not repaired" do
  def listed_kept_entry(id, company_id, note)
    {
      "id" => id, "company_id" => company_id, "version" => 1, "project_id" => 1, "user_id" => 1, "agent_id" => nil,
      "work_date" => Date.new(2026, 1, 5), "duration" => 60.0, "note" => note, "bill_status" => "unbilled",
      "review_status" => "not_required", "locked" => false, "source" => "manual", "source_metadata" => {},
      "external_run_id" => nil, "external_session_id" => nil, "proof_url" => nil, "proof_metadata" => {},
      "discarded_at" => nil, "created_at" => Time.utc(2026, 1, 5, 9), "updated_at" => Time.utc(2026, 1, 5, 9)
    }
  end

  def listed_kept_checkpoint(entries)
    tables = Timekeeping::Handoff::Checkpoint::TABLES.keys.index_with { [] }
    tables["entries"] = entries
    Timekeeping::Handoff::Checkpoint.build(tables: tables)
  end

  # "A difference is "listed" only when that list has it for the same `company_id` and the same row."
  # It "never repairs to 'intended' behaviour".
  it "keeps a listed difference in the report and leaves the loaded row as it was stored" do
    source_entry = listed_kept_entry(7, 101, "before")
    loaded_entry = listed_kept_entry(7, 101, "after")
    projection_row = loaded_entry.merge(
      "bill_status" => TimesheetEntry.bill_statuses.fetch("unbilled"),
      "review_status" => TimesheetEntry.review_statuses.fetch("not_required")
    )
    checkpoint = listed_kept_checkpoint([loaded_entry])
    correction = Timekeeping::Handoff::Reconciliation::Correction.new(check: :entries, row_key: [7], field: "note")

    result = described_class.run(
      source: listed_kept_checkpoint([source_entry]), checkpoint: checkpoint, projection: [projection_row],
      source_intents: [], intents: [], next_entry_id: 100,
      money_before: { 101 => { company_id: 101, values: {} } },
      money_after: { 101 => { company_id: 101, values: {} } },
      listed_corrections: { 101 => [correction] }
    )
    report = result.companies.fetch(101)

    expect(result.abort?).to be(false)
    expect(report.abort?).to be(false)
    expect(report.unlisted).to eq([])
    expect(report.listed.map { |d| [d.company_id, d.check, d.row_key, d.field] }).to eq([[101, :entries, [7], "note"]])
    expect(checkpoint.rows["entries"].first["note"]).to eq("after")
  end
end

RSpec.describe Timekeeping::Handoff::Reconciliation do
  # "Reconciliation only reads; it writes no billing table and repairs nothing."
  it "reports a difference without writing any billing or entry row and returns the result unrepaired" do
    entry_row = lambda do |note|
      {
        "id" => 7, "company_id" => 501, "version" => 1, "project_id" => 1, "user_id" => 1, "agent_id" => nil,
        "work_date" => Date.new(2026, 1, 5), "duration" => 60.0, "note" => note,
        "bill_status" => TimesheetEntry.bill_statuses.keys.first,
        "review_status" => TimesheetEntry.review_statuses.keys.first, "locked" => false, "source" => "manual",
        "source_metadata" => {}, "external_run_id" => nil, "external_session_id" => nil, "proof_url" => nil,
        "proof_metadata" => {}, "discarded_at" => nil, "created_at" => Time.utc(2026, 1, 5, 9),
        "updated_at" => Time.utc(2026, 1, 5, 9)
      }
    end
    tables_with = lambda do |note|
      Timekeeping::Handoff::Checkpoint::TABLES.keys.index_with { [] }.merge("entries" => [entry_row.call(note)])
    end
    source = Timekeeping::Handoff::Checkpoint.build(tables: tables_with.call("as stored"))
    checkpoint = Timekeeping::Handoff::Checkpoint.build(tables: tables_with.call("changed in copy"))
    projection_row = entry_row.call("as stored").merge(
      "bill_status" => TimesheetEntry.bill_statuses.values.first,
      "review_status" => TimesheetEntry.review_statuses.values.first
    )
    snapshot = { company_id: 501, values: {} }.freeze

    result = described_class.run(
      source:, checkpoint:, projection: [projection_row], source_intents: [], intents: [],
      next_entry_id: 100, money_before: { 501 => snapshot }, money_after: { 501 => snapshot }
    )
    report_before = result.to_h

    writes = []
    record_write = lambda do |*, payload|
      sql = payload[:sql].to_s
      next unless sql.match?(/\A\s*(INSERT|UPDATE|DELETE)/i)
      next if sql.include?("rails_event_viewer")

      writes << sql
    end
    returned = ActiveSupport::Notifications.subscribed(record_write, "sql.active_record") do
      described_class.report(result)
    end

    expect(writes).to eq([])
    expect(returned).to equal(result)
    expect(returned.abort?).to be(true)
    expect(returned.to_h).to eq(report_before)
    expect(checkpoint.rows["entries"].first["note"]).to eq("changed in copy")
    expect(projection_row["note"]).to eq("as stored")
  end
end
